import { getRestaurants } from "@/app/lib/api";
import { Star, MapPin, Clock, Shield, ChefHat, Sparkles, Truck, Salad, Coffee } from "lucide-react";

export default async function RestaurantsPage() {
  const restaurants = await getRestaurants();

  // Calculate stats for the header
  const totalRestaurants = restaurants.length;
  const pureVegCount = restaurants.filter(r => r.pure_veg).length;
  const hasPremium = restaurants.some(r => r.rating >= 4.5);

  // Function to get restaurant type icon
  const getRestaurantIcon = (type: string) => {
    switch (type?.toLowerCase()) {
      case 'cafe':
      case 'coffee':
        return <Coffee className="w-4 h-4" />;
      case 'healthy':
      case 'salad':
        return <Salad className="w-4 h-4" />;
      case 'fast food':
        return <Truck className="w-4 h-4" />;
      default:
        return <ChefHat className="w-4 h-4" />;
    }
  };

  // Function to get rating color
  const getRatingColor = (rating: number) => {
    if (rating >= 4.5) return 'from-amber-500 to-amber-600';
    if (rating >= 4.0) return 'from-emerald-500 to-emerald-600';
    if (rating >= 3.5) return 'from-blue-500 to-blue-600';
    return 'from-gray-500 to-gray-600';
  };

  return (
    <main className="min-h-screen bg-gradient-to-b from-gray-50 to-white">
      {/* Decorative background elements */}
      <div className="absolute top-0 left-0 right-0 h-64 bg-gradient-to-br from-emerald-500/5 via-amber-500/5 to-rose-500/5 pointer-events-none -z-10" />
      <div className="absolute top-20 right-5 w-48 h-48 bg-emerald-300/10 rounded-full blur-3xl pointer-events-none -z-10" />
      <div className="absolute top-40 left-5 w-36 h-36 bg-amber-300/10 rounded-full blur-3xl pointer-events-none -z-10" />

      <div className="p-4 md:p-6">
        {/* Header Section */}
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2 bg-gradient-to-br from-emerald-500 to-emerald-600 rounded-xl shadow-lg">
              <ChefHat className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-gray-900">
                Discover Restaurants
              </h1>
              <p className="text-sm text-gray-500 mt-1">
                {totalRestaurants} amazing places near you
              </p>
            </div>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-3 gap-3 mb-6">
            <div className="bg-white/80 backdrop-blur-sm p-3 rounded-2xl border border-gray-100 shadow-sm">
              <div className="text-center">
                <p className="text-xl font-bold text-gray-900">{totalRestaurants}</p>
                <p className="text-xs text-gray-500 mt-1">Restaurants</p>
              </div>
            </div>
            <div className="bg-white/80 backdrop-blur-sm p-3 rounded-2xl border border-gray-100 shadow-sm">
              <div className="text-center">
                <p className="text-xl font-bold text-gray-900">{pureVegCount}</p>
                <p className="text-xs text-gray-500 mt-1">Pure Veg</p>
              </div>
            </div>
            <div className="bg-white/80 backdrop-blur-sm p-3 rounded-2xl border border-gray-100 shadow-sm">
              <div className="text-center">
                <p className="text-xl font-bold text-gray-900">{hasPremium ? 'Yes' : 'No'}</p>
                <p className="text-xs text-gray-500 mt-1">Premium</p>
              </div>
            </div>
          </div>

          {/* Premium Restaurants Badge */}
          {hasPremium && (
            <div className="bg-gradient-to-r from-amber-50 to-amber-100/30 border border-amber-200/50 rounded-2xl p-3 mb-6">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-gradient-to-br from-amber-500 to-amber-600 rounded-lg">
                  <Sparkles className="w-4 h-4 text-white" />
                </div>
                <div>
                  <p className="text-sm font-semibold text-amber-900">Premium Dining Available</p>
                  <p className="text-xs text-amber-700/80 mt-0.5">Exceptional quality restaurants</p>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Restaurants Grid */}
        <div className="space-y-4">
          {restaurants.map((rest: any, index: number) => (
            <a
              key={rest.id}
              href={`/restaurants/${rest.id}`}
              className="group block"
            >
              <div className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden hover:shadow-xl transition-all duration-300 hover:-translate-y-1 active:scale-[0.99]">
                <div className="p-4">
                  <div className="flex gap-4">
                    {/* Restaurant Image */}
                    <div className="relative flex-shrink-0">
                      <div className="w-20 h-20 rounded-xl overflow-hidden bg-gradient-to-br from-gray-100 to-gray-200">
                        {/* Image placeholder with icon */}
                        <div className="w-full h-full flex items-center justify-center">
                          {getRestaurantIcon(rest.type)}
                          <span className="text-[10px] text-gray-500 absolute bottom-1 left-0 right-0 text-center">
                            {rest.type || 'Restaurant'}
                          </span>
                        </div>
                      </div>
                      
                      {/* Rating Badge */}
                      {rest.rating && (
                        <div className={`absolute -top-2 -right-2 px-2 py-1 rounded-full bg-gradient-to-r ${getRatingColor(rest.rating)} text-white text-xs font-bold shadow-lg`}>
                          {rest.rating}
                        </div>
                      )}
                    </div>

                    {/* Restaurant Info */}
                    <div className="flex-1 min-w-0">
                      {/* Header with name and type */}
                      <div className="flex items-start justify-between gap-2">
                        <div className="flex-1">
                          <h2 className="font-bold text-gray-900 text-sm line-clamp-1">
                            {rest.name}
                          </h2>
                          <div className="flex items-center gap-2 mt-1">
                            <span className="inline-flex items-center gap-1 px-2 py-1 bg-gray-100 text-gray-600 text-xs rounded-full">
                              {getRestaurantIcon(rest.type)}
                              <span>{rest.type || 'Restaurant'}</span>
                            </span>
                            
                            {rest.pure_veg && (
                              <span className="inline-flex items-center gap-1 px-2 py-1 bg-emerald-50 text-emerald-700 text-xs rounded-full border border-emerald-200">
                                <Shield className="w-3 h-3" />
                                <span>Pure Veg</span>
                              </span>
                            )}
                          </div>
                        </div>
                      </div>

                      {/* Rating Stars */}
                      {rest.rating && (
                        <div className="flex items-center gap-1 mt-2">
                          {[...Array(5)].map((_, i) => (
                            <Star
                              key={i}
                              className={`w-3 h-3 ${
                                i < Math.floor(rest.rating)
                                  ? 'fill-amber-400 text-amber-400'
                                  : 'fill-gray-200 text-gray-200'
                              }`}
                            />
                          ))}
                          <span className="text-xs text-gray-500 ml-1">
                            ({rest.rating}/5)
                          </span>
                        </div>
                      )}

                      {/* Location and Timing */}
                      <div className="space-y-1 mt-3">
                        {rest.location && (
                          <div className="flex items-center gap-2 text-xs text-gray-600">
                            <MapPin className="w-3.5 h-3.5 text-gray-400" />
                            <span className="line-clamp-1">{rest.location}</span>
                          </div>
                        )}
                        
                        {rest.timing && (
                          <div className="flex items-center gap-2 text-xs text-gray-600">
                            <Clock className="w-3.5 h-3.5 text-gray-400" />
                            <span>{rest.timing}</span>
                          </div>
                        )}
                      </div>

                      {/* Features */}
                      <div className="flex flex-wrap gap-1 mt-3">
                        {rest.delivery_time && (
                          <span className="px-2 py-1 bg-blue-50 text-blue-600 text-xs rounded-full">
                            🚚 {rest.delivery_time} min
                          </span>
                        )}
                        {rest.min_order && (
                          <span className="px-2 py-1 bg-amber-50 text-amber-600 text-xs rounded-full">
                            ₹{rest.min_order} min order
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>

                {/* Bottom CTA */}
                <div className="border-t border-gray-100 p-3 bg-gray-50/50">
                  <div className="flex items-center justify-between">
                    <span className="text-xs text-gray-500">
                      Tap to view menu
                    </span>
                    <div className="flex items-center gap-1 text-emerald-600">
                      <span className="text-sm font-semibold">View Menu</span>
                      <svg 
                        className="w-4 h-4 transform group-hover:translate-x-1 transition-transform" 
                        fill="none" 
                        stroke="currentColor" 
                        viewBox="0 0 24 24"
                      >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                      </svg>
                    </div>
                  </div>
                </div>
              </div>
            </a>
          ))}
        </div>

        {/* Footer Stats */}
        <div className="mt-8 pt-6 border-t border-gray-100">
          <div className="text-center">
            <p className="text-sm text-gray-500">
              Showing {totalRestaurants} of {totalRestaurants} restaurants
            </p>
            <p className="text-xs text-gray-400 mt-2">
              All restaurants • Fresh food daily • Easy ordering
            </p>
          </div>
        </div>

        {/* Empty State */}
        {restaurants.length === 0 && (
          <div className="text-center py-16">
            <div className="w-24 h-24 bg-gradient-to-br from-gray-100 to-gray-200 rounded-full flex items-center justify-center mx-auto mb-4">
              <ChefHat className="w-12 h-12 text-gray-400" />
            </div>
            <h3 className="text-xl font-semibold text-gray-900 mb-2">
              No Restaurants Found
            </h3>
            <p className="text-gray-500 max-w-md mx-auto">
              We're working to add restaurants in your area. Check back soon!
            </p>
          </div>
        )}
      </div>
    </main>
  );
}